-- === Enums (+versions, values) ===
INSERT INTO enums ("name", "owner", "enum_type", "value_type", "description") VALUES ('base.g.node.class', 'gridworks-energy', 'versioned', 'string', 'Universal physical ontology classification for Grid Nodes')
  ON CONFLICT ("name") DO UPDATE SET "owner" = EXCLUDED."owner", "enum_type" = EXCLUDED."enum_type", "value_type" = EXCLUDED."value_type", "description" = EXCLUDED."description";
INSERT INTO enum_versions ("enum", "version", "schema_url", "title", "description", "default_symbol", "status", "created") VALUES ('base.g.node.class', '000', 'https://schemas.electricity.works/enums/base.g.node.class/000', 'base.g.node.class', 'Ontology classification for Grid Nodes (GNodes) used to describe their structural relationship to the physical electric grid. Values identify whether a node represents a physical metered boundary, a physical topological structure, a market coordination constraint, or a purely logical entity.
Every GNode SHALL declare exactly one base.g.node.class value.
', 'Logical', 'published', '2026-02-22T16:43:00Z')
  ON CONFLICT ("enum", "version") DO UPDATE SET "schema_url" = EXCLUDED."schema_url", "title" = EXCLUDED."title", "description" = EXCLUDED."description", "default_symbol" = EXCLUDED."default_symbol", "status" = EXCLUDED."status", "created" = EXCLUDED."created";
INSERT INTO enum_values ("enum_version", "symbol", "idx", "description") VALUES ('base.g.node.class/000', 'TerminalAsset', 0, 'A physical transactive asset such as a heat pump, hot water heater, residential battery,  electric vehicle, or any other end-use device located behind an atomic metered point.
')
  ON CONFLICT ("enum_version", "symbol") DO UPDATE SET "idx" = EXCLUDED."idx", "description" = EXCLUDED."description";
INSERT INTO enum_values ("enum_version", "symbol", "idx", "description") VALUES ('base.g.node.class/000', 'LeafTransactiveNode', 1, 'The atomic metered unit of the grid. Represents the smallest indivisible metering boundary capable of participating in markets or entering Dispatch Contracts on behalf of a TerminalAsset. Every TerminalAsset is associated with exactly one LeafTransactiveNode.
')
  ON CONFLICT ("enum_version", "symbol") DO UPDATE SET "idx" = EXCLUDED."idx", "description" = EXCLUDED."description";
INSERT INTO enum_values ("enum_version", "symbol", "idx", "description") VALUES ('base.g.node.class/000', 'ConnectivityNode', 2, 'A physical topological node in the electric power system where conductors join, split, or change configuration. Conceptually aligned with the ConnectivityNode in the IEC 61970/61968 CIM (Common Information Model), but simplified for distribution-level modeling and OPF applications.
')
  ON CONFLICT ("enum_version", "symbol") DO UPDATE SET "idx" = EXCLUDED."idx", "description" = EXCLUDED."description";
INSERT INTO enum_values ("enum_version", "symbol", "idx", "description") VALUES ('base.g.node.class/000', 'MarketMaker', 3, 'A physical constraint point in the conductor topology that requires localized market coordination. Identified as a grid location (e.g., feeder constraint, transformer limit) where a MarketMaker actor computes local prices for balancing and constraint compliance. See [market-maker](https://gridworks.readthedocs.io/en/latest/market-maker.html).
')
  ON CONFLICT ("enum_version", "symbol") DO UPDATE SET "idx" = EXCLUDED."idx", "description" = EXCLUDED."description";
INSERT INTO enum_values ("enum_version", "symbol", "idx", "description") VALUES ('base.g.node.class/000', 'Logical', 4, 'A non-physical Grid Node whose identity carries no inherent conductor-topology or metering semantics. Used for purely logical or service-level nodes such as SCADA, forecasting services, market-maker actors, simulation nodes, or organizational microservices. Logical nodes may coordinate with or operate on physical nodes, but do not themselves represent physical grid structure.
')
  ON CONFLICT ("enum_version", "symbol") DO UPDATE SET "idx" = EXCLUDED."idx", "description" = EXCLUDED."description";
INSERT INTO enums ("name", "owner", "enum_type", "value_type", "description") VALUES ('buffer.regulation.mode', 'gridworks-energy', 'literal', 'string', 'Operating mode that governs how tightly the House0 buffer tank is regulated.')
  ON CONFLICT ("name") DO UPDATE SET "owner" = EXCLUDED."owner", "enum_type" = EXCLUDED."enum_type", "value_type" = EXCLUDED."value_type", "description" = EXCLUDED."description";
INSERT INTO enum_versions ("enum", "version", "schema_url", "title", "description", "default_symbol", "status", "created") VALUES ('buffer.regulation.mode', '000', 'https://schemas.electricity.works/enums/buffer.regulation.mode/000', 'buffer.regulation.mode', 'Governs how the House0 buffer tank is operated.
', 'Normal', 'published', '2026-03-16T14:14:00Z')
  ON CONFLICT ("enum", "version") DO UPDATE SET "schema_url" = EXCLUDED."schema_url", "title" = EXCLUDED."title", "description" = EXCLUDED."description", "default_symbol" = EXCLUDED."default_symbol", "status" = EXCLUDED."status", "created" = EXCLUDED."created";
INSERT INTO enum_values ("enum_version", "symbol", "idx", "description") VALUES ('buffer.regulation.mode/000', 'Normal', 0, 'Normal mode uses the full range of the buffer thermal store. Charging begins when the buffer is declared empty, as determined by the lowest available buffer temperature sensor dropping below a threshold temperature. The buffer is declared full when the highest buffer temperature sensor rises above a threshold temperature. Thresholds are derived from required source water temperature calculations that account for house performance and weather forecasts.
')
  ON CONFLICT ("enum_version", "symbol") DO UPDATE SET "idx" = EXCLUDED."idx", "description" = EXCLUDED."description";
INSERT INTO enum_values ("enum_version", "symbol", "idx", "description") VALUES ('buffer.regulation.mode/000', 'Tight', 1, 'Tight mode keeps the buffer within a narrowly regulated temperature band, permitting frequent charge and discharge transitions to maintain relatively constant buffer energy. Heat pump short-cycling is prevented by alternating between charging the buffer and the store.
')
  ON CONFLICT ("enum_version", "symbol") DO UPDATE SET "idx" = EXCLUDED."idx", "description" = EXCLUDED."description";
