INSERT INTO enum_values ("enum_version", "symbol", "idx", "description") VALUES ('gw.g.node.class/000', 'TerminalAsset', 1, 'A physical transactive asset such as a heat pump, hot water heater, residential battery,  electric vehicle, or any other end-use device located behind an atomic metered point.
