INSERT INTO enums ("name", "owner", "enum_type", "value_type", "description") VALUES ('gw1.system.mode', 'gridworks-energy', 'versioned', 'string', 'System operational mode for HVAC control.')
  ON CONFLICT ("name") DO UPDATE SET "owner" = EXCLUDED."owner", "enum_type" = EXCLUDED."enum_type", "value_type" = EXCLUDED."value_type", "description" = EXCLUDED."description";
INSERT INTO enum_versions ("enum", "version", "schema_url", "title", "description", "default_symbol", "status", "created") VALUES ('gw1.system.mode', '000', 'https://schemas.electricity.works/enums/gw1.system.mode/000', 'gw1.system.mode', '**SCADA system operational mode.** This enum declares the degree of physical actuation authority exercised by SCADA over connected hardware. It is communicated to other actors (e.g. LTN, admin tools, analytics) to establish shared expectations about whether and how physical control actions may occur.
', 'Heating', 'published', '2026-01-14T18:04:00Z')
  ON CONFLICT ("enum", "version") DO UPDATE SET "schema_url" = EXCLUDED."schema_url", "title" = EXCLUDED."title", "description" = EXCLUDED."description", "default_symbol" = EXCLUDED."default_symbol", "status" = EXCLUDED."status", "created" = EXCLUDED."created";
INSERT INTO enum_values ("enum_version", "symbol", "idx", "description") VALUES ('gw1.system.mode/000', 'Heating', 0, 'Normal operational mode. SCADA may actively energize and de-energize actuators in order to provide heating or cooling services. In this mode, SCADA may accept and execute Dispatch Contracts originating from the Leaf Transactive Node (LTN), subject to local safety constraints and configuration.
')
  ON CONFLICT ("enum_version", "symbol") DO UPDATE SET "idx" = EXCLUDED."idx", "description" = EXCLUDED."description";
INSERT INTO enum_values ("enum_version", "symbol", "idx", "description") VALUES ('gw1.system.mode/000', 'Standby', 1, 'Intentional idle mode with active inhibition. SCADA retains control authority over actuators but uses it only to prevent heating or cooling from occurring. This mode is typically used when the system is intentionally paused (e.g. seasonal shutdown, manual override, or safety condition) while still ensuring that uncontrolled equipment such as boilers or heat pumps do not engage.
')
  ON CONFLICT ("enum_version", "symbol") DO UPDATE SET "idx" = EXCLUDED."idx", "description" = EXCLUDED."description";
INSERT INTO enum_values ("enum_version", "symbol", "idx", "description") VALUES ('gw1.system.mode/000', 'MonitorOnly', 2, 'Absolute non-actuation mode. SCADA MUST NOT issue any physical control actions, including relay changes or analog output updates. Telemetry collection, reporting, forecasting, and contract accounting may continue, but all actuators are left untouched. This mode provides a strong guarantee that no physical intervention will be performed by SCADA.
')
  ON CONFLICT ("enum_version", "symbol") DO UPDATE SET "idx" = EXCLUDED."idx", "description" = EXCLUDED."description";
INSERT INTO enums ("name", "owner", "enum_type", "value_type", "description") VALUES ('gw1.heat.call.interpretation', 'gridworks-energy', 'versioned', 'string', 'Defines how a source telemetry channel is interpreted to determine whether a zone is calling for heat.')
  ON CONFLICT ("name") DO UPDATE SET "owner" = EXCLUDED."owner", "enum_type" = EXCLUDED."enum_type", "value_type" = EXCLUDED."value_type", "description" = EXCLUDED."description";
INSERT INTO enum_versions ("enum", "version", "schema_url", "title", "description", "default_symbol", "status", "created") VALUES ('gw1.heat.call.interpretation', '000', 'https://schemas.electricity.works/enums/gw1.heat.call.interpretation/000', 'gw1.heat.call.interpretation', 'Defines how a source telemetry channel is interpreted to determine whether a zone is calling for heat.
', 'DigitalZeroIsActive', 'published', '2026-03-16T14:14:00Z')
  ON CONFLICT ("enum", "version") DO UPDATE SET "schema_url" = EXCLUDED."schema_url", "title" = EXCLUDED."title", "description" = EXCLUDED."description", "default_symbol" = EXCLUDED."default_symbol", "status" = EXCLUDED."status", "created" = EXCLUDED."created";
INSERT INTO enum_values ("enum_version", "symbol", "idx", "description") VALUES ('gw1.heat.call.interpretation/000', 'DigitalZeroIsActive', 0, 'The source channel is treated as a digital signal where a value of zero indicates an active call for heat. This is typically used for opto-isolated GPIO inputs connected to 24 VAC thermostat circuits that pull the input low when energized.
')
  ON CONFLICT ("enum_version", "symbol") DO UPDATE SET "idx" = EXCLUDED."idx", "description" = EXCLUDED."description";
INSERT INTO enum_values ("enum_version", "symbol", "idx", "description") VALUES ('gw1.heat.call.interpretation/000', 'DigitalOneIsActive', 1, 'The source channel is treated as a digital signal where a value of one indicates an active call for heat.
')
  ON CONFLICT ("enum_version", "symbol") DO UPDATE SET "idx" = EXCLUDED."idx", "description" = EXCLUDED."description";
INSERT INTO enum_values ("enum_version", "symbol", "idx", "description") VALUES ('gw1.heat.call.interpretation/000', 'GreaterThanThreshold', 2, 'The source channel is treated as a scalar measurement. A zone is considered to be calling for heat when the absolute value of the source reading exceeds the configured threshold. This mode is typically used for legacy white-wire power measurements.
')
  ON CONFLICT ("enum_version", "symbol") DO UPDATE SET "idx" = EXCLUDED."idx", "description" = EXCLUDED."description";
