INSERT INTO enums ("name", "owner", "enum_type", "value_type", "description") VALUES ('relay.open.or.closed', 'gridworks-energy', 'literal', 'string', 'Binary contact state for a single-pole relay, independent of coil energization.')
  ON CONFLICT ("name") DO UPDATE SET "owner" = EXCLUDED."owner", "enum_type" = EXCLUDED."enum_type", "value_type" = EXCLUDED."value_type", "description" = EXCLUDED."description";
INSERT INTO enum_versions ("enum", "version", "schema_url", "title", "description", "default_symbol", "status", "created") VALUES ('relay.open.or.closed', '000', 'https://schemas.electricity.works/enums/relay.open.or.closed/000', 'relay.open.or.closed', 'Binary state of a single-pole relay contact. Describes whether the relay 
contact is open (not conducting) or closed (conducting), regardless of 
coil energization state.

Note 1: The coil energization required to achieve a contact state depends 
on relay type:
- Normally Open (NO) relay: energized coil → closed contact
- Normally Closed (NC) relay: de-energized coil → closed contact

Note 2: This enum is specifically for single-pole relays with binary states.
Other relay configurations (double-throw, multi-position, latching, etc.) 
require different state enumerations that capture their specific switching 
patterns.
', 'RelayClosed', 'published', '2025-10-14T16:07:00Z')
  ON CONFLICT ("enum", "version") DO UPDATE SET "schema_url" = EXCLUDED."schema_url", "title" = EXCLUDED."title", "description" = EXCLUDED."description", "default_symbol" = EXCLUDED."default_symbol", "status" = EXCLUDED."status", "created" = EXCLUDED."created";
INSERT INTO enum_values ("enum_version", "symbol", "idx", "description") VALUES ('relay.open.or.closed/000', 'RelayClosed', 0, 'Relay contact is closed (conducting)')
  ON CONFLICT ("enum_version", "symbol") DO UPDATE SET "idx" = EXCLUDED."idx", "description" = EXCLUDED."description";
INSERT INTO enum_values ("enum_version", "symbol", "idx", "description") VALUES ('relay.open.or.closed/000', 'RelayOpen', 1, 'Relay contact is open (not conducting)')
  ON CONFLICT ("enum_version", "symbol") DO UPDATE SET "idx" = EXCLUDED."idx", "description" = EXCLUDED."description";
