INSERT INTO type_axioms ("type_version", "number", "axiom_name", "statement") VALUES ('derived.channel.gt/002', 1, 'EmissionSemanticsConsistency', 'EmissionMethod SHALL determine the presence of EmitPeriodS and AsyncEmitDelta as follows:

  OnTrigger → neither EmitPeriodS nor AsyncEmitDelta present
  Periodic → EmitPeriodS present, AsyncEmitDelta absent
  AsyncAndPeriodic → both EmitPeriodS and AsyncEmitDelta present
')
  ON CONFLICT ("type_version", "axiom_name") DO UPDATE SET "number" = EXCLUDED."number", "statement" = EXCLUDED."statement";
INSERT INTO type_axioms ("type_version", "number", "axiom_name", "statement") VALUES ('derived.channel.gt/002', 2, 'OutputUnitQuantityConsistency', 'OutputQuantity SHALL equal the Quantity defined by the canonical gw1.unit.quantity.projection:000 instance for the specified OutputUnit.
')
  ON CONFLICT ("type_version", "axiom_name") DO UPDATE SET "number" = EXCLUDED."number", "statement" = EXCLUDED."statement";
INSERT INTO type_axioms ("type_version", "number", "axiom_name", "statement") VALUES ('derived.channel.gt/002', 3, 'AffineStrategyRequiresCalibration', 'If Strategy equals "affine", then:

  - Parameters SHALL contain a key "Calibration".
  - Parameters.Calibration SHALL be a valid
    linear.one.dimensional.calibration instance.
')
  ON CONFLICT ("type_version", "axiom_name") DO UPDATE SET "number" = EXCLUDED."number", "statement" = EXCLUDED."statement";
INSERT INTO type_axioms ("type_version", "number", "axiom_name", "statement") VALUES ('derived.channel.gt/002', 4, 'SystemModelRequiresParameters', 'If Strategy equals "system-model", then:
  - Parameters SHALL be present.
  - Parameters SHALL contain a key "EnergyModel".
  - Parameters.EnergyModel SHALL include:
      - TypeName
      - Version
')
  ON CONFLICT ("type_version", "axiom_name") DO UPDATE SET "number" = EXCLUDED."number", "statement" = EXCLUDED."statement";
