INSERT INTO type_attributes ("type_version", "attribute_name", "idx", "description", "default", "is_required", "is_list", "primitive_type", "format_ref", "enum_version_ref", "sub_type_version_ref") VALUES ('gw.nolan.layout/000', 'ShNodes', 1, 'List of Spaceheat nodes representing operational roles in the system. Keys are SpaceheatName identifiers. Each node corresponds to a functional role within the hydronic system.', NULL, TRUE, TRUE, NULL, NULL, NULL, 'spaceheat.node.gt/301')
  ON CONFLICT ("type_version", "attribute_name") DO UPDATE SET "idx" = EXCLUDED."idx", "description" = EXCLUDED."description", "default" = EXCLUDED."default", "is_required" = EXCLUDED."is_required", "is_list" = EXCLUDED."is_list", "primitive_type" = EXCLUDED."primitive_type", "format_ref" = EXCLUDED."format_ref", "enum_version_ref" = EXCLUDED."enum_version_ref", "sub_type_version_ref" = EXCLUDED."sub_type_version_ref";
INSERT INTO type_attributes ("type_version", "attribute_name", "idx", "description", "default", "is_required", "is_list", "primitive_type", "format_ref", "enum_version_ref", "sub_type_version_ref") VALUES ('gw.nolan.layout/000', 'DataChannels', 2, 'List of raw telemetry channels produced by the SCADA system.', NULL, TRUE, TRUE, NULL, NULL, NULL, 'data.channel.gt/001')
  ON CONFLICT ("type_version", "attribute_name") DO UPDATE SET "idx" = EXCLUDED."idx", "description" = EXCLUDED."description", "default" = EXCLUDED."default", "is_required" = EXCLUDED."is_required", "is_list" = EXCLUDED."is_list", "primitive_type" = EXCLUDED."primitive_type", "format_ref" = EXCLUDED."format_ref", "enum_version_ref" = EXCLUDED."enum_version_ref", "sub_type_version_ref" = EXCLUDED."sub_type_version_ref";
INSERT INTO type_attributes ("type_version", "attribute_name", "idx", "description", "default", "is_required", "is_list", "primitive_type", "format_ref", "enum_version_ref", "sub_type_version_ref") VALUES ('gw.nolan.layout/000', 'DerivedChannels', 3, 'List of computed telemetry channels derived from other sources, including raw data channels.', NULL, TRUE, TRUE, NULL, NULL, NULL, 'derived.channel.gt/002')
  ON CONFLICT ("type_version", "attribute_name") DO UPDATE SET "idx" = EXCLUDED."idx", "description" = EXCLUDED."description", "default" = EXCLUDED."default", "is_required" = EXCLUDED."is_required", "is_list" = EXCLUDED."is_list", "primitive_type" = EXCLUDED."primitive_type", "format_ref" = EXCLUDED."format_ref", "enum_version_ref" = EXCLUDED."enum_version_ref", "sub_type_version_ref" = EXCLUDED."sub_type_version_ref";
