  ON CONFLICT ("type_version", "attribute_name") DO UPDATE SET "idx" = EXCLUDED."idx", "description" = EXCLUDED."description", "default" = EXCLUDED."default", "is_required" = EXCLUDED."is_required", "is_list" = EXCLUDED."is_list", "primitive_type" = EXCLUDED."primitive_type", "format_ref" = EXCLUDED."format_ref", "enum_version_ref" = EXCLUDED."enum_version_ref", "sub_type_version_ref" = EXCLUDED."sub_type_version_ref";
INSERT INTO type_attributes ("type_version", "attribute_name", "idx", "description", "default", "is_required", "is_list", "primitive_type", "format_ref", "enum_version_ref", "sub_type_version_ref") VALUES ('gw.nolan.layout/000', 'DeviceTypes', 5, 'List of device types (e.g. the make/model) represented by the system components', NULL, TRUE, TRUE, NULL, NULL, NULL, NULL)
  ON CONFLICT ("type_version", "attribute_name") DO UPDATE SET "idx" = EXCLUDED."idx", "description" = EXCLUDED."description", "default" = EXCLUDED."default", "is_required" = EXCLUDED."is_required", "is_list" = EXCLUDED."is_list", "primitive_type" = EXCLUDED."primitive_type", "format_ref" = EXCLUDED."format_ref", "enum_version_ref" = EXCLUDED."enum_version_ref", "sub_type_version_ref" = EXCLUDED."sub_type_version_ref";
INSERT INTO type_attributes ("type_version", "attribute_name", "idx", "description", "default", "is_required", "is_list", "primitive_type", "format_ref", "enum_version_ref", "sub_type_version_ref") VALUES ('gw.nolan.layout/000', 'Hydronic', 6, 'Hydronic system configuration parameters used to determine required SpaceHeat nodes, including store tank indexing and other topology-driving values.', NULL, TRUE, FALSE, NULL, NULL, NULL, NULL)
  ON CONFLICT ("type_version", "attribute_name") DO UPDATE SET "idx" = EXCLUDED."idx", "description" = EXCLUDED."description", "default" = EXCLUDED."default", "is_required" = EXCLUDED."is_required", "is_list" = EXCLUDED."is_list", "primitive_type" = EXCLUDED."primitive_type", "format_ref" = EXCLUDED."format_ref", "enum_version_ref" = EXCLUDED."enum_version_ref", "sub_type_version_ref" = EXCLUDED."sub_type_version_ref";
INSERT INTO type_axioms ("type_version", "number", "axiom_name", "statement") VALUES ('gw.nolan.layout/000', 1, 'NolanGNodeSet', 'the GNodes object SHALL contain exactly three entries with keys "Scada", "TerminalAsset", and "LeafTransactiveNode". These keys SHALL match the GNodeClass of their corresponding g.node.gt objects.
The Alias of the LeafTransactiveNode SHALL be the parent alias of both the Scada and TerminalAsset aliases (i.e., the Scada alias SHALL equal "<LeafAlias>.scada" and the TerminalAsset alias SHALL equal "<LeafAlias>.ta").
')
  ON CONFLICT ("type_version", "axiom_name") DO UPDATE SET "number" = EXCLUDED."number", "statement" = EXCLUDED."statement";
INSERT INTO type_axioms ("type_version", "number", "axiom_name", "statement") VALUES ('gw.nolan.layout/000', 2, 'GlobalIdUniqueness', 'The following identifiers SHALL be globally unique across the entire layout:

  - ShNode.ShNodeId
  - Component.ComponentId
  - DeviceType.ComponentAttributeClassId
  - DataChannel.Id
  - DerivedChannel.Id
  - GNode.GNodeId

No identifier value appearing in any one of the above sets SHALL appear in any other set.
    
')
  ON CONFLICT ("type_version", "axiom_name") DO UPDATE SET "number" = EXCLUDED."number", "statement" = EXCLUDED."statement";
INSERT INTO type_axioms ("type_version", "number", "axiom_name", "statement") VALUES ('gw.nolan.layout/000', 3, 'DeviceTypeReferenceIntegrity', 'For every Component, there SHALL exist a DeviceType whose ComponentAttributeClassId  equals the Component''s ComponentAttributeClassId.
')
  ON CONFLICT ("type_version", "axiom_name") DO UPDATE SET "number" = EXCLUDED."number", "statement" = EXCLUDED."statement";
INSERT INTO type_axioms ("type_version", "number", "axiom_name", "statement") VALUES ('gw.nolan.layout/000', 4, 'ComponentConfigListExistence', 'Every Component SHALL contain a ConfigList field, which MAY be empty.
')
  ON CONFLICT ("type_version", "axiom_name") DO UPDATE SET "number" = EXCLUDED."number", "statement" = EXCLUDED."statement";
INSERT INTO type_axioms ("type_version", "number", "axiom_name", "statement") VALUES ('gw.nolan.layout/000', 5, 'HydronicStructure', 'The Hydronic object SHALL contain:
  - TotalStoreTanks: a non-negative integer
  - StoreTankIndices: a list of integers
  - ZoneList: a list of strings
  - CriticalZoneList: a list of strings
  - ZoneKwhPerDegFList: a list of numeric values

StoreTankIndices SHALL:
  - contain unique integer values
  - be sorted in ascending order
  - have length equal to TotalStoreTanks
  - contain only integers in the range 1 through 6 inclusive

ZoneList SHALL:
  - contain at least one element
  - contain unique values
  - contain only valid SpaceheatName values

CriticalZoneList SHALL:
  - be a sublist of ZoneList

ZoneKwhPerDegFList SHALL:
  - contain only numeric values greater than or equal to zero
  - have length equal to the length of ZoneList
  - be index-aligned with ZoneList (i.e., the ith element corresponds to ZoneList[i])
')
  ON CONFLICT ("type_version", "axiom_name") DO UPDATE SET "number" = EXCLUDED."number", "statement" = EXCLUDED."statement";
INSERT INTO type_axioms ("type_version", "number", "axiom_name", "statement") VALUES ('gw.nolan.layout/000', 6, 'ShNodeNameUniqueness', 'The Name field SHALL be unique across all ShNodes.
')
  ON CONFLICT ("type_version", "axiom_name") DO UPDATE SET "number" = EXCLUDED."number", "statement" = EXCLUDED."statement";
INSERT INTO type_axioms ("type_version", "number", "axiom_name", "statement") VALUES ('gw.nolan.layout/000', 7, 'CoreShNodesExistenceAndActorClass', 'The ShNodes list SHALL contain a node with each of the following Names. The Name and ActorClass of each such node SHALL match the following mapping:

  "s"                → ActorClass "PrimaryScada"
  "s2"               → ActorClass "SecondaryScada"
  "power-meter"      → ActorClass "PowerMeter"
  "ltn"              → ActorClass "NoActor"
  "la"               → ActorClass "LeafAlly"
  "lc"               → ActorClass "LocalControl"
  "admin"            → ActorClass "NoActor"
  "auto"             → ActorClass "NoActor"
  "derived-generator"→ ActorClass "DerivedGenerator"

No additional ShNode with any of the above Names SHALL exist.
')
  ON CONFLICT ("type_version", "axiom_name") DO UPDATE SET "number" = EXCLUDED."number", "statement" = EXCLUDED."statement";
INSERT INTO type_axioms ("type_version", "number", "axiom_name", "statement") VALUES ('gw.nolan.layout/000', 8, 'HydronicShNodesExistenceAndActorClass', 'The ShNodes list SHALL contain a node with each of the following Names.
# Local control nodes:
  - "n"
  - "backup"
  - "scada-blind"
  - "pico-cycler"
  - "hp-boss"

# Transactive asset nodes:
  - "heat-pump"
  - "buffer-top-elt"
  - "buffer-bottom-elt"
  - "store-top-elt"
  - "store-bottom-elt"

# Pump nodes:
  - "dist-pump"
  - "store-pump"

# Pipe temperature nodes:
  - "dist-swt"
  - "dist-rwt"
  - "hp-lwt"
  - "hp-ewt"
  - "store-hot-pipe"
  - "store-cold-pipe"
  - "buffer-hot-pipe"
  - "buffer-cold-pipe"

# Buffer temperature nodes:
  - "buffer-depth1"
  - "buffer-depth2"
  - "buffer-depth3"

ActorClass constraints:
  - The node with Name "pico-cycler" SHALL have ActorClass "PicoCycler".
  - The node with Name "hp-boss" SHALL have ActorClass "HpBoss"

All other nodes listed above MAY have ActorClass "NoActor" or another ActorClass consistent with their function.
')
  ON CONFLICT ("type_version", "axiom_name") DO UPDATE SET "number" = EXCLUDED."number", "statement" = EXCLUDED."statement";
INSERT INTO type_axioms ("type_version", "number", "axiom_name", "statement") VALUES ('gw.nolan.layout/000', 9, 'NolanNodesExistenceAndActorClass', 'The ShNodes list SHALL contain nodes with the following Names.

  Pipe temperature nodes:
    - "floor-swt"
    
')
  ON CONFLICT ("type_version", "axiom_name") DO UPDATE SET "number" = EXCLUDED."number", "statement" = EXCLUDED."statement";
INSERT INTO type_axioms ("type_version", "number", "axiom_name", "statement") VALUES ('gw.nolan.layout/000', 10, 'HandleTopologyRequirements', 'Define the effective Handle of a ShNode as:
  - Handle, if Handle is present
  - otherwise Name

The following effective Handle values SHALL exist across the ShNodes:

  - "ltn"
  - "auto"
  - "ltn.la"
  - "auto.lc"

  - "auto.pico-cycler"
  - "auto.lc.n"
  - "auto.lc.backup"
  - "auto.lc.scada-blind"
  - "auto.lc.n.hp-boss"

  - "auto.pico-cycler.vdc-relay-gpio-23"

  - "auto.lc.n.buffer-top-relay"
  - "auto.lc.n.buffer-bottom-relay"
  - "auto.lc.n.store-top-relay"
  - "auto.lc.n.store-bottom-relay"

Closure:
  - For every effective Handle listed above, all prefix handles SHALL
    correspond to the effective Handle of another ShNode.
')
  ON CONFLICT ("type_version", "axiom_name") DO UPDATE SET "number" = EXCLUDED."number", "statement" = EXCLUDED."statement";
INSERT INTO type_axioms ("type_version", "number", "axiom_name", "statement") VALUES ('gw.nolan.layout/000', 11, 'ActorHierarchyClosure', 'For every ShNode with a non-null ActorHierarchyName, all prefix handles obtained by iteratively removing the final segment SHALL correspond to the ActorHierarchyName of another ShNode in the ShNodes list.
Additionally, each such parent ShNode SHALL have ActorClass not equal to "NoActor".
')
  ON CONFLICT ("type_version", "axiom_name") DO UPDATE SET "number" = EXCLUDED."number", "statement" = EXCLUDED."statement";
INSERT INTO type_axioms ("type_version", "number", "axiom_name", "statement") VALUES ('gw.nolan.layout/000', 12, 'ZoneShNodeStructure', 'Let ZoneList be the list of zone labels defined in Hydronic.
For each zone label Z at index i (1-based) in ZoneList:

  1. Required node names:
    - A ShNode with Name equal to "zone{i}-{Z}" SHALL exist.
    - A ShNode with Name equal to "zone{i}-{Z}-whitewire" SHALL exist.
    - A ShNode with Name equal to "zone{i}-{Z}-stat" SHALL exist.
    - A ShNode with Name equal to "zone{i}-{Z}-floor" SHALL exist.

  2. Index constraints:
    - i SHALL be in the range 1 through 6 inclusive.

  3. Uniqueness:
    - No additional ShNode names matching the pattern "zone{i}-{Z}*"
      SHALL exist other than those defined above
')
  ON CONFLICT ("type_version", "axiom_name") DO UPDATE SET "number" = EXCLUDED."number", "statement" = EXCLUDED."statement";
INSERT INTO type_axioms ("type_version", "number", "axiom_name", "statement") VALUES ('gw.nolan.layout/000', 13, 'TankShNodeStructure', 'Let TotalStoreTanks be the integer defined in Hydronic.
1. Store tank nodes:
  - For each tank index i in the range 1 through TotalStoreTanks inclusive:

      - A ShNode with Name equal to "tank{i}" SHALL exist.

      - The following ShNodes SHALL exist:
          - "tank{i}-depth1"
          - "tank{i}-depth2"
          - "tank{i}-depth3"

2. Index constraints:
  - TotalStoreTanks SHALL be in the range 0 through 6 inclusive.

3. Closure:
  - If a ShNode Name matches either pattern:
      - "tank{i}-depth{j}"
      - "buffer-depth{j}"
    then j SHALL be one of 1, 2, or 3, and i SHALL be a positive integer
    less than or equal to TotalStoreTanks.
')
  ON CONFLICT ("type_version", "axiom_name") DO UPDATE SET "number" = EXCLUDED."number", "statement" = EXCLUDED."statement";
INSERT INTO type_axioms ("type_version", "number", "axiom_name", "statement") VALUES ('gw.nolan.layout/000', 14, 'ComponentReferenceIntegrity', 'For every ShNode:
  - If ComponentId is present, a component with that ComponentId
    SHALL exist in Components.
  - If BoardComponentId is present, a component with that ComponentId
    SHALL exist in Components.
')
  ON CONFLICT ("type_version", "axiom_name") DO UPDATE SET "number" = EXCLUDED."number", "statement" = EXCLUDED."statement";
INSERT INTO type_axioms ("type_version", "number", "axiom_name", "statement") VALUES ('gw.nolan.layout/000', 15, 'CoreChannelExistence', 'There SHALL exist exactly one DerivedChannel whose Name is equal to "asset-electric-power".
')
  ON CONFLICT ("type_version", "axiom_name") DO UPDATE SET "number" = EXCLUDED."number", "statement" = EXCLUDED."statement";
INSERT INTO type_axioms ("type_version", "number", "axiom_name", "statement") VALUES ('gw.nolan.layout/000', 16, 'HydronicChannelExistence', 'The following channels SHALL exist in the union of DataChannels and DerivedChannels:

  # Power reading channels
    - "heat-pump-pwr"
    - "dist-pump-pwr"
    - "store-pump-pwr"
    - "buffer-top-elt-pwr"
    - "buffer-bottom-elt-pwr"
    - "store-top-elt-pwr"
    - "store-bottom-elt-pwr"

  # Effective pipe temperature channels
    - "dist-swt"
    - "dist-rwt"
    - "hp-lwt"
    - "hp-ewt"
    - "store-hot-pipe"
    - "store-cold-pipe"
    - "buffer-hot-pipe"
    - "buffer-cold-pipe"

  # Effective buffer temperature channels:
    - "buffer-depth1"
    - "buffer-depth2"
    - "buffer-depth3"

  # Pipe flows
    - "dist-flow"
    - "primary-flow"
    - "store-flow"

  # Energy estimates
    - "required-energy"
    - "usable-energy"

  # Relay states 
    - "vdc-relay"
    - "buffer-top-relay" 
    - "buffer-bottom-relay"
    - "store-top-relay"
    - "store-bottom-relay"
')
  ON CONFLICT ("type_version", "axiom_name") DO UPDATE SET "number" = EXCLUDED."number", "statement" = EXCLUDED."statement";
INSERT INTO type_axioms ("type_version", "number", "axiom_name", "statement") VALUES ('gw.nolan.layout/000', 17, 'NolanChannelExistence', 'The following channels SHALL exist in the union of DataChannels and DerivedChannels:
  - "floor-swt"
')
  ON CONFLICT ("type_version", "axiom_name") DO UPDATE SET "number" = EXCLUDED."number", "statement" = EXCLUDED."statement";
INSERT INTO type_axioms ("type_version", "number", "axiom_name", "statement") VALUES ('gw.nolan.layout/000', 18, 'TankChannelStructure', 'For every ShNode whose Name is required by TankShNodeStructure and matches either pattern:

  - "buffer-depth{j}"
  - "tank{i}-depth{j}"

there SHALL exist exactly one channel in the union of DataChannels and DerivedChannels whose Name is equal to the ShNode Name.
')
  ON CONFLICT ("type_version", "axiom_name") DO UPDATE SET "number" = EXCLUDED."number", "statement" = EXCLUDED."statement";
INSERT INTO type_axioms ("type_version", "number", "axiom_name", "statement") VALUES ('gw.nolan.layout/000', 19, 'Axiom19', NULL)
  ON CONFLICT ("type_version", "axiom_name") DO UPDATE SET "number" = EXCLUDED."number", "statement" = EXCLUDED."statement";
INSERT INTO type_axioms ("type_version", "number", "axiom_name", "statement") VALUES ('gw.nolan.layout/000', 20, 'ChannelBindingIntegrity', 'For each DataChannel and DerivedChannel, the following SHALL hold:

  1. ShNode references:
    - If AboutNodeName is present, there SHALL exist a ShNode with
      Name equal to AboutNodeName.
    - If CapturedByNodeName is present, there SHALL exist a ShNode
      with Name equal to CapturedByNodeName.

  2. Channel name uniqueness:
    - The Name field SHALL be unique across the union of all
      DataChannels and DerivedChannels.
')
  ON CONFLICT ("type_version", "axiom_name") DO UPDATE SET "number" = EXCLUDED."number", "statement" = EXCLUDED."statement";
INSERT INTO type_axioms ("type_version", "number", "axiom_name", "statement") VALUES ('gw.nolan.layout/000', 21, 'ComponentDataChannelBijection', 'Let C be the set of all ChannelName values appearing in the ConfigList of all components.
Let D be the set of all Name values of DataChannels.
  - C SHALL equal D.    
')
  ON CONFLICT ("type_version", "axiom_name") DO UPDATE SET "number" = EXCLUDED."number", "statement" = EXCLUDED."statement";
INSERT INTO type_axioms ("type_version", "number", "axiom_name", "statement") VALUES ('gw.nolan.layout/000', 22, 'ChannelCaptureConsistency', 'For each ShNode N:
If N is associated with a component whose ConfigList has non-zero length,
then for each such ChannelName:
  Let DC be the DataChannel with Name equal to ChannelName.
  - DC.CapturedByNodeName SHALL equal N.Name.    
')
  ON CONFLICT ("type_version", "axiom_name") DO UPDATE SET "number" = EXCLUDED."number", "statement" = EXCLUDED."statement";
INSERT INTO type_axioms ("type_version", "number", "axiom_name", "statement") VALUES ('gw.nolan.layout/000', 23, 'RelayBoardConfigBijection', '1. For every ShNode with ActorClass equal to "Relay":

    - BoardComponentId SHALL be present.

    - There SHALL exist exactly one component in Components whose
        ComponentId equals BoardComponentId.

    - Within that component''s ConfigList there SHALL exist exactly
    one object with:

        - TypeName equal to "relay.actor.config"
        - Version equal to "002"
        - ActorName equal to the ShNode Name.

2.For every component in Components, and for every object in that
  component''s ConfigList with:

  - TypeName equal to "relay.actor.config"
  - Version equal to "002"

  there SHALL exist exactly one ShNode with:
  
  - ActorClass equal to "Relay"
  - Name equal to the ActorName of that config.
')
  ON CONFLICT ("type_version", "axiom_name") DO UPDATE SET "number" = EXCLUDED."number", "statement" = EXCLUDED."statement";
INSERT INTO type_axioms ("type_version", "number", "axiom_name", "statement") VALUES ('gw.nolan.layout/000', 24, 'PowerMeteringNodeChannelConsistency', 'For each ShNode:

  - ShNode.InPowerMetering SHALL be true if and only if there exists
    exactly one DataChannel such that:

      - DataChannel.AboutNodeName equals the ShNode Name
      - DataChannel.TelemetryName equals "PowerW"
      - DataChannel.InPowerMetering is true
')
  ON CONFLICT ("type_version", "axiom_name") DO UPDATE SET "number" = EXCLUDED."number", "statement" = EXCLUDED."statement";
INSERT INTO type_axioms ("type_version", "number", "axiom_name", "statement") VALUES ('gw.nolan.layout/000', 25, 'AssetElectricPowerSemantics', 'The DerivedChannel with Name equal to "asset-electric-power" SHALL satisfy:
  - Strategy SHALL be "sum".
  - InputChannelNames SHALL equal the set of Names of all DataChannels
    for which InPowerMetering is true.
  - OutputUnit SHALL be "Watts".
  - OutputQuantity SHALL be "Power".
  - EmissionMethod SHALL be "AsyncAndPeriodic".
')
  ON CONFLICT ("type_version", "axiom_name") DO UPDATE SET "number" = EXCLUDED."number", "statement" = EXCLUDED."statement";
INSERT INTO type_axioms ("type_version", "number", "axiom_name", "statement") VALUES ('gw.nolan.layout/000', 26, 'PowerMeteringChannelSemantics', 'For each DataChannel whose Name is one of:

  - "heat-pump-pwr"
  - "buffer-top-elt-pwr"
  - "buffer-bottom-elt-pwr"
  - "store-top-elt-pwr"
  - "store-bottom-elt-pwr"

the following SHALL hold:

  - InPowerMetering SHALL be true.
  - AboutNodeName SHALL equal the channel Name with the suffix "-pwr"
    removed.
')
  ON CONFLICT ("type_version", "axiom_name") DO UPDATE SET "number" = EXCLUDED."number", "statement" = EXCLUDED."statement";
INSERT INTO type_axioms ("type_version", "number", "axiom_name", "statement") VALUES ('gw.nolan.layout/000', 27, 'PipeTemperatureChannelSemantics', 'For each channel whose Name is one of:

  - "dist-swt"
  - "dist-rwt"
  - "hp-lwt"
  - "hp-ewt"
  - "store-hot-pipe"
  - "store-cold-pipe"
  - "buffer-hot-pipe"
  - "buffer-cold-pipe"

there SHALL exist exactly one channel in the union of DataChannels and DerivedChannels such that:

  - AboutNodeName SHALL equal the channel Name.

  - If the channel is a DerivedChannel:
      - OutputUnit SHALL be "FahrenheitX100".
      - OutputQuantity SHALL be "Temperature".

  - If the channel is a DataChannel:
      - TelemetryName SHALL be one of:
          - "WaterTempCTimes1000"
          - "CelsiusTimes100"
')
  ON CONFLICT ("type_version", "axiom_name") DO UPDATE SET "number" = EXCLUDED."number", "statement" = EXCLUDED."statement";
INSERT INTO type_axioms ("type_version", "number", "axiom_name", "statement") VALUES ('gw.nolan.layout/000', 28, 'TankTemperatureChannelSemantics', 'For each channel whose Name matches either pattern:

  - "buffer-depth{j}"
  - "tank{i}-depth{j}"

there SHALL exist exactly one DerivedChannel such that:

  - Name SHALL equal the channel Name.
  - AboutNodeName SHALL equal the channel Name.
  - OutputUnit SHALL be "FahrenheitX100".
  - OutputQuantity SHALL be "Temperature".
  - Strategy SHALL be "affine" or "identity".
')
  ON CONFLICT ("type_version", "axiom_name") DO UPDATE SET "number" = EXCLUDED."number", "statement" = EXCLUDED."statement";
INSERT INTO type_axioms ("type_version", "number", "axiom_name", "statement") VALUES ('gw.nolan.layout/000', 29, 'PipeFlowChannelSemantics', 'For each DataChannel whose Name is one of:

  - "dist-flow"
  - "primary-flow"
  - "store-flow"
')
  ON CONFLICT ("type_version", "axiom_name") DO UPDATE SET "number" = EXCLUDED."number", "statement" = EXCLUDED."statement";
INSERT INTO type_axioms ("type_version", "number", "axiom_name", "statement") VALUES ('gw.nolan.layout/000', 30, 'EnergyChannelSemantics', 'For each DerivedChannel whose Name is one of:
  - "usable-energy"
  - "required-energy"

the following SHALL hold:
  - Strategy SHALL be "system-model".
  - OutputUnit SHALL be "WattHours".
  - OutputQuantity SHALL be "Energy".
  - EmissionMethod SHALL be "Periodic".
  - EmitPeriodS SHALL be 60.
  - InputChannelNames SHALL be empty.

  - Parameters.EnergyModel.TypeName SHALL equal:
      - "gw0.usable.energy.layered" for "usable-energy"
      - "gw0.required.energy.layered" for "required-energy"
')
  ON CONFLICT ("type_version", "axiom_name") DO UPDATE SET "number" = EXCLUDED."number", "statement" = EXCLUDED."statement";
INSERT INTO type_axioms ("type_version", "number", "axiom_name", "statement") VALUES ('gw.nolan.layout/000', 31, 'VdcRelaySemantics', 'The DataChannel with Name "vdc-relay" SHALL satisfy the following: Let N be the ShNode with Name equal to the DataChannel''s AboutNodeName

  1. Structural channel properties:
    - TelemetryName SHALL equal "RelayState".

  2. ShNode binding:
    - N SHALL have ActorClass equal to "Relay".

  3. Handle topology:
    - The effective Handle of N SHALL equal
      "auto.pico-cycler.<AboutNodeName>".

  4. Relay configuration:

  - The relay.actor.config associated with N (as defined by
    RelayBoardConfigBijection) SHALL have:

      - StateType equal to "relay.closed.or.open"
      - EventType equal to "change.relay.state"
      - WiringConfig equal to "NormallyClosed"
')
  ON CONFLICT ("type_version", "axiom_name") DO UPDATE SET "number" = EXCLUDED."number", "statement" = EXCLUDED."statement";
INSERT INTO type_axioms ("type_version", "number", "axiom_name", "statement") VALUES ('gw.nolan.layout/000', 32, 'ElementRelaySemantics', 'For each DataChannel whose Name is one of:

  - "buffer-top-relay"
  - "buffer-bottom-relay"
  - "store-top-relay"
  - "store-bottom-relay"

let N be the ShNode with Name equal to the DataChannel''s AboutNodeName.
The following SHALL hold:

  1. Channel properties:
    - TelemetryName SHALL equal "RelayState".

  2. ShNode binding:
    - N SHALL have ActorClass equal to "Relay".

  3. Relay configuration:

    - The relay.actor.config associated with N (as defined by
      RelayBoardConfigBijection) SHALL have:

        - StateType equal to "relay.closed.or.open"
        - EventType equal to "change.relay.state"
        - WiringConfig equal to "NormallyOpen"
')
  ON CONFLICT ("type_version", "axiom_name") DO UPDATE SET "number" = EXCLUDED."number", "statement" = EXCLUDED."statement";
INSERT INTO type_axioms ("type_version", "number", "axiom_name", "statement") VALUES ('gw.nolan.layout/000', 33, 'ZoneFailsafeRelaySemantics', 'For each DataChannel whose Name matches the pattern:

  - "zone{i}-{label}-failsafe-relay{n}"

let N be the ShNode with Name equal to the DataChannel''s AboutNodeName.
The following SHALL hold:

  1. Channel properties:
    - TelemetryName SHALL equal "RelayState".

  2. ShNode binding:
    - N SHALL have ActorClass equal to "Relay".

  3. Relay configuration:

    - The relay.actor.config associated with N (as defined by
      RelayBoardConfigBijection) SHALL have:

        - StateType equal to "heatcall.source"
        - EventType equal to "change.heatcall.source"
        - WiringConfig equal to "DoubleThrow"
')
  ON CONFLICT ("type_version", "axiom_name") DO UPDATE SET "number" = EXCLUDED."number", "statement" = EXCLUDED."statement";
INSERT INTO type_axioms ("type_version", "number", "axiom_name", "statement") VALUES ('gw.nolan.layout/000', 34, 'ZoneOpsRelaySemantics', 'For each DataChannel whose Name matches the pattern:

  - "zone{i}-{label}-ops-relay{n}"

let N be the ShNode with Name equal to the DataChannel''s AboutNodeName.
The following SHALL hold:

  1. Channel properties:
    - TelemetryName SHALL equal "RelayState".

  2. ShNode binding:
    - N SHALL have ActorClass equal to "Relay".

  3. Relay configuration:

    - The relay.actor.config associated with N (as defined by
      RelayBoardConfigBijection) SHALL have:

        - StateType equal to "relay.closed.or.open"
        - EventType equal to "change.relay.state"
        - WiringConfig equal to "NormallyOpen"
')
  ON CONFLICT ("type_version", "axiom_name") DO UPDATE SET "number" = EXCLUDED."number", "statement" = EXCLUDED."statement";
INSERT INTO type_axioms ("type_version", "number", "axiom_name", "statement") VALUES ('gw.nolan.layout/000', 35, 'ZoneRoomTempChannelSemantics', 'For each zone label Z at index i (1-based) in ZoneList, let base be "zone{i}-{Z}".
The channel with Name "{base}-temp" SHALL be a DerivedChannel such that:

  - AboutNodeName SHALL equal "{base}".
  - OutputUnit SHALL be "FahrenheitX100".
  - OutputQuantity SHALL be "Temperature".
')
  ON CONFLICT ("type_version", "axiom_name") DO UPDATE SET "number" = EXCLUDED."number", "statement" = EXCLUDED."statement";
INSERT INTO type_axioms ("type_version", "number", "axiom_name", "statement") VALUES ('gw.nolan.layout/000', 36, 'ZoneSetpointChannelSemantics', 'For each zone label Z at index i (1-based) in ZoneList, let base be "zone{i}-{Z}".
The channel with Name "{base}-set" SHALL be a DerivedChannel such that:

  - AboutNodeName SHALL equal "{base}-stat".
  - OutputUnit SHALL be "FahrenheitX100".
  - OutputQuantity SHALL be "Temperature".
')
  ON CONFLICT ("type_version", "axiom_name") DO UPDATE SET "number" = EXCLUDED."number", "statement" = EXCLUDED."statement";
INSERT INTO type_axioms ("type_version", "number", "axiom_name", "statement") VALUES ('gw.nolan.layout/000', 37, 'ZoneFloorTempChannelSemantics', 'For each zone label Z at index i (1-based) in ZoneList, let base be "zone{i}-{Z}".
The channel with Name "{base}-floor-temp" SHALL be a DerivedChannel such that:

  - AboutNodeName SHALL equal "{base}".
  - OutputUnit SHALL be "FahrenheitX100".
  - OutputQuantity SHALL be "Temperature".
')
  ON CONFLICT ("type_version", "axiom_name") DO UPDATE SET "number" = EXCLUDED."number", "statement" = EXCLUDED."statement";
INSERT INTO type_axioms ("type_version", "number", "axiom_name", "statement") VALUES ('gw.nolan.layout/000', 38, 'HeatCallChannelSemantics', 'For each zone label Z at index i (1-based) in ZoneList, let base be "zone{i}-{Z}".
The channel with Name "{base}-heat-call" SHALL be a DerivedChannel such that:

  - AboutNodeName SHALL equal "{base}-whitewire".
  - Strategy SHALL be "heat-call".
  - InputChannelNames SHALL contain exactly one element C such that:
    - C SHALL be the Name of a DataChannel.
    - C SHALL match the pattern "{base}-whitewire-*".
    - The DataChannel with Name C SHALL have:
        - AboutNodeName equal to "{base}-whitewire".
  - OutputQuantity SHALL be "Unitless".
  - OutputUnit SHALL be "Unitless".
  - EmissionMethod SHALL be "AsyncAndPeriodic".
  - Parameters SHALL contain:
      - "Interpretation"
  - Parameters SHALL contain:
    - "Interpretation"
    - Parameters["Interpretation"] SHALL be an object with:
      - TypeName equal to "heatcall.interpretation"
      - Version equal to "000"
')
  ON CONFLICT ("type_version", "axiom_name") DO UPDATE SET "number" = EXCLUDED."number", "statement" = EXCLUDED."statement";
