INSERT INTO type_axioms ("type_version", "number", "axiom_name", "statement") VALUES ('relay.actor.config/003', 1, 'AsyncCaptureConsistency', 'If AsyncCapture is true, then AsyncCaptureDelta SHALL be present.
')
  ON CONFLICT ("type_version", "axiom_name") DO UPDATE SET "number" = EXCLUDED."number", "statement" = EXCLUDED."statement";
INSERT INTO type_axioms ("type_version", "number", "axiom_name", "statement") VALUES ('relay.actor.config/003', 2, 'CapturePollingConsistency', 'If PollPeriodMs is present, then CapturePeriodMs (CapturePeriodS * 1000) SHALL be greater than PollPeriodMs. If CapturePeriodMs is less than 10 times PollPeriodMs, then CapturePeriodMs SHALL be a multiple of PollPeriodMs.
')
  ON CONFLICT ("type_version", "axiom_name") DO UPDATE SET "number" = EXCLUDED."number", "statement" = EXCLUDED."statement";
INSERT INTO type_axioms ("type_version", "number", "axiom_name", "statement") VALUES ('relay.actor.config/003', 3, 'RelayEventEnumConsistency', 'If EventType equals "change.relay.state", then DeEnergizingEvent and EnergizingEvent SHALL both be valid values of change.relay.state:000.
')
  ON CONFLICT ("type_version", "axiom_name") DO UPDATE SET "number" = EXCLUDED."number", "statement" = EXCLUDED."statement";
INSERT INTO type_axioms ("type_version", "number", "axiom_name", "statement") VALUES ('relay.actor.config/003', 4, 'RelayStateEnumConsistency', 'If StateType equals "relay.closed.or.open", then DeEnergizedState and EnergizedState SHALL both be valid values of relay.closed.or.open:000.
')
  ON CONFLICT ("type_version", "axiom_name") DO UPDATE SET "number" = EXCLUDED."number", "statement" = EXCLUDED."statement";
INSERT INTO type_axioms ("type_version", "number", "axiom_name", "statement") VALUES ('relay.actor.config/003', 5, 'RelayEventStateMatch', 'If EventType equals "change.relay.state" and StateType equals "relay.closed.or.open", then:

  - DeEnergizingEvent "CloseRelay" SHALL imply DeEnergizedState "RelayClosed"
  - DeEnergizingEvent "OpenRelay" SHALL imply DeEnergizedState "RelayOpen"
  - EnergizingEvent "CloseRelay" SHALL imply EnergizedState "RelayClosed"
  - EnergizingEvent "OpenRelay" SHALL imply EnergizedState "RelayOpen"
')
  ON CONFLICT ("type_version", "axiom_name") DO UPDATE SET "number" = EXCLUDED."number", "statement" = EXCLUDED."statement";
