INSERT INTO type_axioms ("type_version", "number", "axiom_name", "statement") VALUES ('relay.actor.config/002', 1, 'EventEnumConsistency', 'If EventType names a known enum, then DeEnergizingEvent and EnergizingEvent SHALL both be valid values of that enum.
')
  ON CONFLICT ("type_version", "axiom_name") DO UPDATE SET "number" = EXCLUDED."number", "statement" = EXCLUDED."statement";
INSERT INTO type_axioms ("type_version", "number", "axiom_name", "statement") VALUES ('relay.actor.config/002', 2, 'StateEnumConsistency', 'If StateType names a known enum, then DeEnergizedState and EnergizedState SHALL both be valid values of that enum.
')
  ON CONFLICT ("type_version", "axiom_name") DO UPDATE SET "number" = EXCLUDED."number", "statement" = EXCLUDED."statement";
INSERT INTO type_axioms ("type_version", "number", "axiom_name", "statement") VALUES ('relay.actor.config/002', 3, 'EventStateSemanticMatch', 'EnergizingEvent and DeEnergizingEvent SHALL correspond semantically to transitions into EnergizedState and DeEnergizedState respectively.
')
  ON CONFLICT ("type_version", "axiom_name") DO UPDATE SET "number" = EXCLUDED."number", "statement" = EXCLUDED."statement";
INSERT INTO type_axioms ("type_version", "number", "axiom_name", "statement") VALUES ('relay.actor.config/002', 4, 'ClosedOpenWiringConsistency', 'If:

  - StateType equals "relay.closed.or.open"
  - EventType equals "change.relay.state"
  - WiringConfig equals "NormallyClosed"

then:

  - DeEnergizedState SHALL equal "RelayClosed"
  - DeEnergizingEvent SHALL equal "CloseRelay"
  - EnergizedState SHALL equal "RelayOpen"
  - EnergizingEvent SHALL equal "OpenRelay"

If:

  - StateType equals "relay.closed.or.open"
  - EventType equals "change.relay.state"
  - WiringConfig equals "NormallyOpen"

then:

  - DeEnergizedState SHALL equal "RelayOpen"
  - DeEnergizingEvent SHALL equal "OpenRelay"
  - EnergizedState SHALL equal "RelayClosed"
  - EnergizingEvent SHALL equal "CloseRelay"
')
  ON CONFLICT ("type_version", "axiom_name") DO UPDATE SET "number" = EXCLUDED."number", "statement" = EXCLUDED."statement";
