INSERT INTO type_axioms ("type_version", "number", "axiom_name", "statement") VALUES ('scada.control.capabilities/001', 1, 'ActorClassConsistency', 'a. All nodes in RelayNodes SHALL have ActorClass equal to Relay. b. All nodes in DacNodes SHALL have ActorClass equal to ZeroTenOutputer.
')
  ON CONFLICT ("type_version", "axiom_name") DO UPDATE SET "number" = EXCLUDED."number", "statement" = EXCLUDED."statement";
INSERT INTO type_axioms ("type_version", "number", "axiom_name", "statement") VALUES ('scada.control.capabilities/001', 2, 'HandleTerminalMatchesName', 'For every node in RelayNodes and DacNodes, Handle SHALL be present and its final dot-separated token SHALL equal Name.
')
  ON CONFLICT ("type_version", "axiom_name") DO UPDATE SET "number" = EXCLUDED."number", "statement" = EXCLUDED."statement";
INSERT INTO type_axioms ("type_version", "number", "axiom_name", "statement") VALUES ('scada.control.capabilities/001', 3, 'AboutNodesAreControlNodes', 'The set of ControlChannels.AboutNodeName values SHALL equal the set of RelayNodes.Name and DacNodes.Name values.
')
  ON CONFLICT ("type_version", "axiom_name") DO UPDATE SET "number" = EXCLUDED."number", "statement" = EXCLUDED."statement";
INSERT INTO type_axioms ("type_version", "number", "axiom_name", "statement") VALUES ('scada.control.capabilities/001', 4, 'I2cRelayComponentChannelControlNodeConsistency', 'a. The set of ActorName values in I2cRelayComponent.ConfigList SHALL equal the set of RelayNodes.Name values. b. For each relay actor config in I2cRelayComponent.ConfigList, ChannelName SHALL equal the Name of the ControlChannels entry whose AboutNodeName is that relay actor config''s ActorName.
')
  ON CONFLICT ("type_version", "axiom_name") DO UPDATE SET "number" = EXCLUDED."number", "statement" = EXCLUDED."statement";
